def _kupiec_term(count: int, probability: float) -> float:
    """One ``count * ln(probability)`` log-likelihood term.

    ``0 * ln 0`` is defined as 0 here, so boundary outcomes (no breach
    or every day breaching) stay well defined.
    """
    if count == 0:
        return 0.0
    return count * math.log(probability)

def _var_backtest(self, payload: dict) -> dict:
    currency = payload.get("currency", "USD")
    if not isinstance(currency, str) or len(currency) == 0:
        raise InvalidInput()

    confidence = payload.get("confidence")
    if not _is_finite_number(confidence) or not 0 < confidence < 1:
        raise InvalidInput()

    significance = payload.get("significance", 0.05)
    if not _is_finite_number(significance) or not 0 < significance < 1:
        raise InvalidInput()

    observations_raw = payload.get("observations")
    if not isinstance(observations_raw, list):
        raise InvalidInput()
    if len(observations_raw) > MAX_OBSERVATIONS:
        raise RequestTooLarge(f"at most {MAX_OBSERVATIONS} observations are allowed")
    if len(observations_raw) < 2:
        raise InvalidInput()

    rows: list[dict] = []
    dates: list[str] = []
    for observation in observations_raw:
        if not isinstance(observation, dict):
            raise InvalidInput()
        date = observation.get("date")
        if not _is_nonempty_str(date):
            raise InvalidInput()
        var = _as_float(observation.get("var"))
        if var < 0.0:
            raise InvalidInput()
        realized_pnl = _as_float(observation.get("realized_pnl"))
        loss = -realized_pnl
        if not math.isfinite(loss):
            raise InvalidInput()
        dates.append(date)
        rows.append(
            {
                "date": date,
                "var": var,
                "realized_pnl": realized_pnl,
                "loss": loss,
                "breach": loss > var,
            }
        )

    seen_dates: set[str] = set()
    for date in dates:
        if date in seen_dates:
            raise InvalidInput("duplicate_observation", "observation dates must be unique")
        seen_dates.add(date)

    n = len(rows)
    x = sum(1 for row in rows if row["breach"])
    breach_rate = x / n

    # Kupiec (1995) proportion-of-failures unconditional-coverage test.
    p = 1.0 - confidence
    q = x / n
    constrained = _kupiec_term(n - x, 1.0 - p) + _kupiec_term(x, p)
    unconstrained = _kupiec_term(n - x, 1.0 - q) + _kupiec_term(x, q)
    log_likelihood_ratio = constrained - unconstrained
    # The constrained MLE cannot truly beat the unconstrained one; a
    # small negative remainder is rounding noise and reads as zero.
    if log_likelihood_ratio < 0.0:
        log_likelihood_ratio = 0.0
    lr_statistic = -2.0 * log_likelihood_ratio
    if not math.isfinite(lr_statistic):
        raise InvalidInput(message="backtest computation overflowed")
    p_value = math.erfc(math.sqrt(lr_statistic / 2.0))
    if not math.isfinite(p_value):
        raise InvalidInput(message="backtest computation overflowed")

    return {
        "currency": currency,
        "confidence": confidence,
        "significance": significance,
        "observations": rows,
        "observation_count": n,
        "breach_count": x,
        "breach_rate": breach_rate,
        "kupiec": {
            "lr_statistic": lr_statistic,
            "p_value": p_value,
            "accepted": p_value >= significance,
        },
    }

